//! 🧬️ SemioTextMutation — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `SemioTextSnapshot` shape (one index-keyed, id-less ordered
//! collection — `runs`, each carrying its own nested `marks` collection) per
//! `../SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/`📓️fanout-brief.md`. `impl protocol::Mutation`/
//! `SemanticMutation` below are generated by `#[derive(dsl::Mutations)]` — never hand-written.
//!
//! `runs: Vec<SemioTextRun>` has no stable id (addressing rule #3): `insert-run`/`remove-run`
//! address by index (inserted = FINAL-state, removed = BASE-state), `reorder-runs` moves one run
//! within the sequence, `edit-run` replaces one run's authored `content` body, `change-run-
//! language` sets one run's BCP-47 tag. `marks: Vec<SemioTextMark>` (nested inside each run) is
//! itself an id-less ordered collection, addressed the same way one level deeper: `add-mark`/
//! `remove-mark` take `{run_index, index}`, `add`/`remove` per the core verb table's "attach/detach
//! a set-like member" entry.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `🦀️.rs` (the stdio
//! W2 agent owns `🦀️.rs`, so no self-wiring `#[path = "."]` blocks are needed here).

use crate::standards::v1::subsets::text::schema::diff::SemioTextDiff;
use crate::standards::v1::subsets::text::schema::snapshot::SemioTextSnapshot;

//#region 🔖️Leaves
use super::add_mark;
use super::change_run_language;
use super::edit_run;
use super::insert_run;
use super::remove_mark;
use super::remove_run;
use super::reorder_runs;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<SemioTextSnapshot, SemioTextMutation>`
/// payload struct declared in the corresponding triad leaf's `🦠️mutation/🦀️.rs`. This
/// plugin crate reaches the derive through the `dsl` extern-crate alias `🦀️.rs` declares
/// (`extern crate semio_framework_os_kernel as dsl;`), the same spelling every other stdio subset's
/// eventual `dsl::Mutations` derive uses (confirmed against `din4108`'s already-compiling facet,
/// this ticket's binding reference).
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::Mutations)]
#[mutations(snapshot = SemioTextSnapshot, diff = SemioTextDiff, schema = "s.stdio.semio.text")]
pub enum SemioTextMutation {
    InsertRun(insert_run::InsertRun),
    RemoveRun(remove_run::RemoveRun),
    EditRun(edit_run::EditRun),
    ChangeRunLanguage(change_run_language::ChangeRunLanguage),
    ReorderRuns(reorder_runs::ReorderRuns),
    AddMark(add_mark::AddMark),
    RemoveMark(remove_mark::RemoveMark),
}

/// 🏷️ Kebab-case spelling of every `SemioTextMutation` variant, in declaration order — the
/// vocabulary the `semio-v1-text` mutation catalog (`../../🔣️oracle.json`) declares and
/// `🔤️mutate-semio-text`'s exhaustive test case measures itself against. `kinds_match_the_enum_and_
/// the_catalog` below is what keeps this list honest against the enum, since the framework never
/// parses Rust.
pub const KINDS: &[&str] = &["insert-run", "remove-run", "edit-run", "change-run-language", "reorder-runs", "add-mark", "remove-mark"];
//#endregion 🔖️Mutations

//#region 🔖️Apply
/// ▶️ Applies a mutation to `snapshot` in place, returning the diff — kept from the pre-wave facet
/// (consumed by `../🦀️.rs`'s `SemioTextBuilderConstruction::mutate`).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn apply_semio_text_mutation(snapshot: &mut SemioTextSnapshot, mutation: &SemioTextMutation) -> protocol::MutationOutcome<SemioTextDiff> {
    use protocol::Mutation;
    let outcome = <SemioTextMutation as Mutation<SemioTextSnapshot>>::diff(mutation, snapshot);
    outcome.apply_to(snapshot)
}

/// ↩️ Computes `mutation`'s own inverse against `base` — a thin wrapper around
/// `protocol::Mutation::inverse` so external Rust callers that cannot name this crate's private
/// `protocol` extern-crate item (the `🔤️mutate-semio-text` test adapter, whose `inverse-<kind>`
/// scenarios need a mutation's own computed inverse) can still reach the inverse law that
/// [`apply_semio_text_mutation`] alone cannot. Same shape as `🧰️kit`'s `inverse_semio_kit_mutation`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn inverse_semio_text_mutation(mutation: &SemioTextMutation, base: &SemioTextSnapshot) -> Vec<SemioTextMutation> {
    use protocol::Mutation;
    <SemioTextMutation as Mutation<SemioTextSnapshot>>::inverse(mutation, base)
}

/// 📥️ Decodes this facet's own externally-tagged (`{"<VariantName>": {<snake_case payload>}}`) JSON
/// projection — no `#[value(rename_all)]` sits on this enum or its payload structs, which is
/// exactly the shape the committed `<kind>/🧪️tests/<fixture>/🦠️mutation/🔣️.json` vectors
/// carry — into a real [`SemioTextMutation`]. Same rationale as
/// `../📸️snapshot/🦀️.rs`'s `decode_semio_text_snapshot_json`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn decode_semio_text_mutation_json(text: &str) -> Result<SemioTextMutation, String> {
    pack::from_json_str(text).map_err(|error| error.to_string())
}
//#endregion 🔖️Apply

